def f(g):
    out=[r[:] for r in g]; H,W=len(g),len(g[0]); bg=g[0][0]
    colsep=[]; rowsep=[]
    for c in range(W):
        if sum(1 for r in range(H) if g[r][c]==2)>=H: colsep.append(c)
    for r in range(H):
        if sum(1 for c in range(W) if g[r][c]==2)>=W: rowsep.append(r)
    if colsep: sep=colsep[0]; axis='h'
    else: sep=rowsep[0]; axis='v'
    cells=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg and g[r][c]!=2 and (axis=='h' or c!=sep) and (axis=='v' or r!=sep)]
    rs=[r for r,c,_ in cells]; cs=[c for _,c,_ in cells]
    shift=0
    if axis=='h':
        lo,hi=min(cs),max(cs)
        if lo>sep: shift=(sep+1)-lo      # shape on right: slide left until left edge touches sep
        elif hi<sep: shift=(sep-1)-hi    # shape on left: slide right until right edge touches sep
        else: shift=0
    else:
        lo,hi=min(rs),max(rs)
        if lo>sep: shift=(sep+1)-lo
        elif hi<sep: shift=(sep-1)-hi
        else: shift=0
    for r,c,v in cells:
        nr=r+shift if axis=='v' else r
        nc=c+shift if axis=='h' else c
        out[nr][nc]=v
    for r in range(H):
        for c in range(W):
            if axis=='v' and r==sep or axis=='h' and c==sep:
                out[r][c]=8
    return out
